mapper.select:
SELECT COUNT(1) as totalNumber, COALESCE(SUM(if(complete_date is not NULL,1,0)),0) as completeNumber FROM patrol_task
and start_date >= #{param.period.begin}
and start_date <= #{param.period.end}

SELECT
count(1)
FROM
patrol_task


        and start_date >= #{param.period.begin}


        and start_date <= #{param.period.end}

SELECT COALESCE(SUM(if(`status` = 'IN_EXECUTION',1,0)),0) as inExecutionNumber, COALESCE(SUM(if(`status` = 'TO_BE_RECEIVED',1,0)),0) as toBeReceivedNumber, COALESCE(SUM(if(`status` = 'FINISHED',1,0)),0) as finishedNumber, COALESCE(SUM(if(`status` = 'FINISHED' AND result = 'ABNORMAL',1,0)),0) as abnormalFinishedNumber FROM patrol_task
and start_date >= #{param.period.begin}
and start_date <= #{param.period.end}

SELECT
COUNT(DISTINCT route_id)
FROM
patrol_task


        and start_date >= #{param.period.begin}


        and start_date <= #{param.period.end}

SELECT COUNT(DISTINCT pl.id) FROM patrol_task pt INNER JOIN patrol_task_location ptl on pt.id = ptl.task_id INNER JOIN patrol_location pl on ptl.location_id = pl.id
and pt.start_date >= #{param.period.begin}
and pt.start_date <= #{param.period.end}
